{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table redtape_db.maplemonk.redtape_db_Mazhar_FactItems as SELECT order_date, category_mapped, division, city, gender, REPLACE(SKU,\'`\',\'\') sku, REGEXP_REPLACE(REPLACE(SKU,\'`\',\'\'), \'-[^-]*$\', \'\') article, product_name_final, sale_quantity ,sales_value ,selling_price ,tax ,return_quantity ,return_sales ,\"Available Quantity\" closing_inventory FROM ( SELECT s.order_date ,s.sku ,s.product_name_final ,sale_quantity ,sales_value ,selling_price ,tax ,return_quantity ,return_sales ,\"Available Quantity\" ,coalesce(s.division,pgd.division) division ,city ,pgd.gender ,COALESCE(pma.category,pmf.category,pmac.category) category_mapped FROM ( SELECT coalesce(a.order_date,m.order_date) order_date, coalesce(a.sku,m.sku) sku, coalesce(a.product_name_final,m.product_name) product_name_final, division, city, \"Available Quantity\", sale_quantity, sales_value, selling_price, tax, return_quantity, return_sales FROM ( SELECT order_date::DATE AS order_date, REPLACE(sku,\'`\',\'\') AS sku, upper(product_name_final) product_name_final, division, city, SUM(quantity) sale_quantity, SUM(gross_sales_before_tax) sales_value, SUM(selling_price) selling_price, SUM(tax) tax, FROM redtape_db.maplemonk.redtape_db_sales_consolidated WHERE ORDER_STATUS IN ( \'ASSIGNED\', \'CONFIRMED\', \'MANIFEST SCANNED\', \'OPEN\', \'PRINTED\', \'READY TO DISPATCH\', \'RETURNED\', \'SHIPPED\' ) group by 1,2,3,4,5 ) a LEFT JOIN ( SELECT sku, product_name, order_date, \"Available Quantity\" FROM ( SELECT sku, \"Product Name\" AS product_name, \"Report Generated Date\"::DATE AS order_date, sum(\"Available Quantity\")\"Available Quantity\", FROM redtape_db.maplemonk.easyecom_redtape_inventory_snapshot WHERE \"Report Generated Date\" IS NOT NULL GROUP BY 1,2,3 ) ) m ON a.order_date = m.order_date AND a.sku = m.sku LEFT JOIN( SELECT * FROM( SELECT sku, return_date::DATE AS return_date, SUM(total_returned_quantity) return_quantity, SUM(total_return_amount) return_sales FROM redtape_db.maplemonk.redtape_db_returns_consolidated GROUP BY 1,2) )n ON a.order_date = n.return_date AND a.sku = n.sku )s LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY code ORDER BY 1) rw FROM redtape_db.maplemonk.product_mapping_gender_division ) WHERE rw = 1 ) pgd ON UPPER(LEFT(REPLACE(s.SKU,\'`\',\'\'),3)) = pgd.code LEFT JOIN ( SELECT * FROM ( SELECT code, \"FOR SELL THRU\" category, ROW_NUMBER() OVER (PARTITION BY code ORDER BY 1) rw FROM redtape_db.maplemonk.product_mapping_apparel ) WHERE rw = 1 ) pma ON UPPER(LEFT(REPLACE(s.SKU,\'`\',\'\'),3)) = pma.code LEFT JOIN ( SELECT * FROM ( SELECT code, gategory category, ROW_NUMBER() OVER (PARTITION BY code ORDER BY 1) rw FROM redtape_db.maplemonk.product_mapping_footwear ) WHERE rw = 1 ) pmf ON UPPER(LEFT(REPLACE(s.SKU,\'`\',\'\'),3)) = pmf.code LEFT JOIN ( SELECT * FROM ( SELECT code, category, ROW_NUMBER() OVER (PARTITION BY code ORDER BY 1) rw FROM redtape_db.maplemonk.product_mapping_accessories ) WHERE rw = 1 ) pmac ON UPPER(LEFT(REPLACE(s.SKU,\'`\',\'\'),3)) = pmac.code);",
                    "transaction": true
                }
            ) }}
